INSERT INTO public.email_templates (template_key, subject, html_body, description)
VALUES 
('training_call_rescheduled', '📅 Rescheduled: {{title}}', '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background:#f9f5f0;font-family:Georgia,serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f9f5f0;padding:40px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.08);"><tr><td style="background:#BB1B56;padding:28px 32px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;letter-spacing:0.5px;">📅 Training Call Rescheduled</h1></td></tr><tr><td style="padding:32px;"><p style="color:#333;font-size:15px;margin:0 0 16px 0;">Hi {{firstName}},</p><p style="color:#333;font-size:15px;margin:0 0 16px 0;">The following training call has been <strong>rescheduled</strong>:</p><div style="background:#fdf6ee;border-left:4px solid #BB1B56;padding:16px 20px;border-radius:0 8px 8px 0;margin:0 0 16px 0;"><h2 style="margin:0 0 8px 0;color:#333;font-size:17px;">{{title}}</h2>{{description}}<p style="color:#333;font-size:14px;margin:0 0 4px 0;"><strong>Previous time:</strong> {{previousTime}}</p><p style="color:#BB1B56;font-size:14px;margin:0 0 4px 0;font-weight:700;"><strong>New time:</strong> {{localTime}}</p><p style="color:#666;font-size:13px;margin:0;">Duration: {{durationMinutes}} minutes · Timezone: {{timezone}}</p></div>{{recurrenceText}}{{zoomButton}}<p style="color:#666;font-size:13px;margin:24px 0 0 0;">Please update your calendar accordingly. An updated .ics file is attached.</p></td></tr><tr><td style="background:#fdf6ee;padding:20px 32px;text-align:center;border-top:1px solid #f0e6d9;"><p style="margin:0;color:#999;font-size:12px;">13 Creators · Training Programme</p></td></tr></table></td></tr></table></body></html>', 'Sent to all invitees when a training call is rescheduled to a new date/time'),
('training_call_cancelled', '❌ Cancelled: {{title}}', '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background:#f9f5f0;font-family:Georgia,serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f9f5f0;padding:40px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.08);"><tr><td style="background:#BB1B56;padding:28px 32px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;letter-spacing:0.5px;">❌ Training Call Cancelled</h1></td></tr><tr><td style="padding:32px;"><p style="color:#333;font-size:15px;margin:0 0 16px 0;">Hi {{firstName}},</p><p style="color:#333;font-size:15px;margin:0 0 16px 0;">The following training call has been <strong>cancelled</strong>:</p><div style="background:#fdf6ee;border-left:4px solid #dc2626;padding:16px 20px;border-radius:0 8px 8px 0;margin:0 0 16px 0;"><h2 style="margin:0 0 8px 0;color:#333;font-size:17px;text-decoration:line-through;">{{title}}</h2>{{description}}<p style="color:#666;font-size:14px;margin:0 0 4px 0;">Was scheduled: {{localTime}}</p><p style="color:#666;font-size:13px;margin:0;">Duration: {{durationMinutes}} minutes</p></div><p style="color:#666;font-size:14px;margin:16px 0 0 0;">Please remove this from your calendar. No further action is needed.</p></td></tr><tr><td style="background:#fdf6ee;padding:20px 32px;text-align:center;border-top:1px solid #f0e6d9;"><p style="margin:0;color:#999;font-size:12px;">13 Creators · Training Programme</p></td></tr></table></td></tr></table></body></html>', 'Sent to all invitees when a training call is cancelled')
